const input = $json;
const catalog = input.catalog ?? {};
const intent = (catalog.intents ?? []).find((row) => row.intentKey === input.intent);
const binding = (catalog.workflowBindings ?? []).find((row) => row.workflowKey === input.workflowKey);
const rule = (catalog.qualityRules ?? []).find((row) => row.intentKey === input.intent);
const qualityBinding = rule && (catalog.workflowBindings ?? []).find((row) => row.workflowKey === rule.qualityWorkflowKey);
const slots = (catalog.slots ?? []).filter((row) => row.intentKey === input.intent);
const present = slots.filter((slot) => Boolean(input.leadData?.[slot.slotKey]));
const totalWeight = slots.reduce((sum, slot) => sum + Math.max(0, Number(slot.qualityWeight ?? 0)), 0);
const presentWeight = present.reduce((sum, slot) => sum + Math.max(0, Number(slot.qualityWeight ?? 0)), 0);
const contactScore = totalWeight ? Math.round((presentWeight / totalWeight) * 100) : 0;
const validationPass = Boolean(input.leadData?.name && (input.leadData?.email || input.leadData?.phone));
if (!input.leadId || !input.tenantId || !input.catalogVersionId || !intent?.active || !binding?.active || !rule || rule.qualityWorkflowKey !== input.qualityWorkflowKey || !qualityBinding?.active || !validationPass) throw new Error('Catalog quality input is invalid');
const intentScore = Math.max(0, Math.min(100, Number(input.intentScore ?? 0)));
const intentConfidence = Math.max(0, Math.min(1, Number(input.intentConfidence ?? 0)));
const score = Math.max(0, Math.min(100, Math.round(intentScore * rule.intentWeight + intentConfidence * 100 * rule.confidenceWeight + contactScore * rule.contactWeight)));
const quality = score >= rule.hotThreshold ? 'hot' : score >= rule.warmThreshold ? 'warm' : score >= rule.nurtureThreshold ? 'nurture' : 'new';
return [{ json: { ...input, score, quality, validationPass, qualityWorkflowKey: rule.qualityWorkflowKey } }];

const source = (typeof $ !== 'undefined' && $('Calculate Catalog Quality').first()?.json) || $json;
if (!source.leadId || !source.tenantId || !Array.isArray(source.conversation)) throw new Error('Conversation summary input is invalid');
const userTurns = source.conversation.filter((message) => message.role === 'user').map((message) => String(message.content ?? '').trim()).filter(Boolean);
const assistantTurns = source.conversation.filter((message) => message.role === 'assistant').map((message) => String(message.content ?? '').trim()).filter(Boolean);
const contactValues = Object.entries(source.leadData ?? {}).filter(([key, value]) => key !== 'interest' && typeof value === 'string').map(([, value]) => value);
const contactTurns = /^(?:\[NAME_\d+\]|\[EMAIL_\d+\]|\[PHONE_\d+\])$/u;
const contextTurns = userTurns.filter((turn) => { const normalized = turn.replace(/[\s.!?,;:]+$/gu, ''); return !contactValues.some((value) => normalized.includes(value)) && !contactTurns.test(normalized); });
const customerRequest = contextTurns.at(-1) ?? 'follow-up requested';
const projectContext = contextTurns.find((turn) => turn !== customerRequest);
const humanIntent = String(source.intent ?? 'lead.capture').replaceAll('.', ' ');
const humanInterest = String(source.leadData?.interest ?? source.intentSummary ?? humanIntent);
const humanQuality = String(source.quality ?? 'unknown').replace(/^\w/u, (letter) => letter.toUpperCase());
const contactStatus = source.leadData?.email || source.leadData?.phone ? 'Provided' : 'Not provided';
const summary = [`Customer request: ${customerRequest}`, ...(projectContext ? [`Project context: ${projectContext}`] : []), `Contact details: ${contactStatus}.`, `Interest: ${humanInterest}.`, `Intent: ${humanIntent}.`, `Lead quality: ${humanQuality} (${source.score ?? 'unknown'}/100).`, `Validation: ${source.validationPass === true ? 'Passed' : 'Not passed'}.`, `Conversation: ${userTurns.length} visitor message(s), ${assistantTurns.length} assistant response(s).`].join('\n').slice(0, 20000);
return [{ json: { ...source, summary } }];
